 p['zhTitle']=p['title'];p['level']='未标注';p['visual']='pending';p['summary']='这道题的样例与官方入口已入库，逐题教学讲解正在补充。请先打开官方题面阅读完整要求。';p['summaryEn']='Samples and official source links are available. The teaching walkthrough is not yet written; read the official statement for complete requirements.';p['hints']=[];p['analysis']='';p['checker']='special' if p['id'] in [1589,1540,1563] else 'tokens';p['testsImported']=0;p['testsTotal']=0
