  zh,tags,level,visual,s,en,analysis,hints=C[p['id']];p.update(zhTitle=zh,tags=tags,level=level,visual=visual,summary=s,summaryEn=en,analysis=analysis,hints=hints,reviewStatus='已核验',reviewedAt='2026-10-02')
  p['reviewEvidence']=p['editorial']
